g.end_sentence();
g.end_sentence();
let player_1 = { let q: &dyn Query = g; Some(asker.controller).expect("a reference that always names a player") };
if let Some(object) = ({ let q: &dyn Query = g; (t_1_raw.get(0).copied().filter(|t| t_1.contains(t)).and_then(|t: Target| t.object()).into_iter().collect::<Vec<_>>()).into_iter().filter(|&o| q.state().obj(o).became.is_none()).collect::<Vec<ObjectId>>() }).first().copied() { let card = g.card_id(&CARD); match cantrip_mechanics::choose::one_of(g, player_1, asker.source, vec![Label::Card(card, 0), Label::Card(card, 1), Label::Card(card, 2)])? { 0 => g.tap(object), 1 => g.untap(object), _ => {} }; }
g.end_sentence();
g.end_sentence();
